Lemma bex_destroy_mid : forall (X : list (Z * Z)) pt vt (L : list (Z * Z)),
  List.NoDup (map fst (X ++ pix_new_live pt vt L)) -> p_data vt <> 0 -> p_cmap vt = 0 ->
